import java.util.Scanner;
public class JThreeBoolean1 {
	public static void main(String[] args) {
		//Alkhatwa 1: Qira madkhalat almustakhdim
		Scanner scan = new Scanner(System.in);
		System.out.println("Adkhil qimat almutaghyyir al-booli al-awwal (true aw false):");
		boolean a = scan.nextBoolean();		
		System.out.println("Adkhil qimat almutaghyyir al-booli al-thani (true aw false):");
		boolean b = scan.nextBoolean();	
		System.out.println("Adkhil qimat almutaghyyir al-booli al-thalith (true aw false):");
		boolean c = scan.nextBoolean();		
		scan.close();
		//Alkhatwa 2: Aktub alibara alboolean litahdid idha kana ahad min althalatha mutaghayyirat boolean sahiha
		boolean value = a || b || c;
		System.out.println(value);
	}
}
